<script setup>
import {ref} from 'vue'; import AdminLayout from '../layouts/AdminLayout.vue'; import PageHeader from '../components/PageHeader.vue'; import {store,persist} from '../mockStore'
const show=ref(false),form=ref({username:'',name:'',role:'TECH',roleLabel:'Técnico',active:true}),msg=ref('')
function add(){if(!form.value.username||!form.value.name)return;form.value.roleLabel=form.value.role==='ADMIN'?'Administrador':form.value.role==='HELPER'?'Ayudante':'Técnico';store.users.push({id:Date.now(),...form.value});persist();form.value={username:'',name:'',role:'TECH',roleLabel:'Técnico',active:true};show.value=false;msg.value='Usuario agregado al prototipo.'}
function toggle(u){u.active=!u.active;persist()}
</script>
<template><AdminLayout><PageHeader>Usuarios y roles<template #subtitle>Representación del control de acceso interno.</template><template #actions><button class="btn btn-primary" @click="show=!show">+ Nuevo usuario</button></template></PageHeader><div v-if="msg" class="alert alert-success py-2">{{msg}}</div><div v-if="show" class="mc-card p-3 mb-3"><div class="row g-2"><div class="col-md-3"><input v-model="form.username" class="form-control" placeholder="Usuario"></div><div class="col-md-4"><input v-model="form.name" class="form-control" placeholder="Nombre"></div><div class="col-md-3"><select v-model="form.role" class="form-select"><option value="ADMIN">Administrador</option><option value="TECH">Técnico</option><option value="HELPER">Ayudante</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100" @click="add">Guardar</button></div></div></div><div class="mc-card p-3 table-responsive"><table class="table mb-0"><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="u in store.users"><td>{{u.username}}</td><td>{{u.name}}</td><td>{{u.roleLabel}}</td><td><span class="badge" :class="u.active?'text-bg-success':'text-bg-secondary'">{{u.active?'Activo':'Inactivo'}}</span></td><td class="text-end"><button class="btn btn-sm btn-outline-secondary" @click="toggle(u)">{{u.active?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></AdminLayout></template>
